public class Main {
    public static void main(String[] args) {
        int[] arr = {3, 6, 9, 12, 15};
        int sum = 0;
        int count = 0;

        for (int i = 0; i < arr.length; i++) {
            if (arr[i] % 3 == 0 && arr[i] % 2 == 0) {
                sum += arr[i];
                count++;
            }
        }

        System.out.println("sum=" + sum);
        System.out.println("count=" + count);
    }
}

def process(numbers):
    result = []
    for n in numbers:
        if n % 2 == 0:
            result.append(n * 2)
        else:
            result.append(n + 10)
    return result


data = [1, 2, 3, 4, 5, 6]
processed = process(data)
total = sum(processed)

print(processed)
print(total)

